            8'ha3: gf_inv = 8'hc6;
            8'ha4: gf_inv = 8'h34;
            8'ha5: gf_inv = 8'hc2;
            8'ha6: gf_inv = 8'h46;
            8'ha7: gf_inv = 8'h05;
            8'ha8: gf_inv = 8'hce;
            8'ha9: gf_inv = 8'h3b;
            8'haa: gf_inv = 8'h0d;
            8'hab: gf_inv = 8'h3c;
            8'hac: gf_inv = 8'h9c;
            8'had: gf_inv = 8'h08;
            8'hae: gf_inv = 8'hbe;
            8'haf: gf_inv = 8'hb7;
            8'hb0: gf_inv = 8'h87;
            8'hb1: gf_inv = 8'he5;
            8'hb2: gf_inv = 8'hee;
            8'hb3: gf_inv = 8'h6b;
            8'hb4: gf_inv = 8'heb;
            8'hb5: gf_inv = 8'hf2;
            8'hb6: gf_inv = 8'hbf;
            8'hb7: gf_inv = 8'haf;
            8'hb8: gf_inv = 8'hc5;
            8'hb9: gf_inv = 8'h64;
            8'hba: gf_inv = 8'h07;
            8'hbb: gf_inv = 8'h7b;
            8'hbc: gf_inv = 8'h95;
            8'hbd: gf_inv = 8'h9a;
            8'hbe: gf_inv = 8'hae;
            8'hbf: gf_inv = 8'hb6;
            8'hc0: gf_inv = 8'h12;
            8'hc1: gf_inv = 8'h59;
            8'hc2: gf_inv = 8'ha5;
            8'hc3: gf_inv = 8'h35;
            8'hc4: gf_inv = 8'h65;
            8'hc5: gf_inv = 8'hb8;
            8'hc6: gf_inv = 8'ha3;
            8'hc7: gf_inv = 8'h9e;
            8'hc8: gf_inv = 8'hd2;
            8'hc9: gf_inv = 8'hf7;
            8'hca: gf_inv = 8'h62;
            8'hcb: gf_inv = 8'h5a;
            8'hcc: gf_inv = 8'h85;
            8'hcd: gf_inv = 8'h7d;
            8'hce: gf_inv = 8'ha8;
            8'hcf: gf_inv = 8'h3a;
            8'hd0: gf_inv = 8'h29;
            8'hd1: gf_inv = 8'h71;
            8'hd2: gf_inv = 8'hc8;
            8'hd3: gf_inv = 8'hf6;
            8'hd4: gf_inv = 8'hf9;
            8'hd5: gf_inv = 8'h43;
            8'hd6: gf_inv = 8'hd7;
            8'hd7: gf_inv = 8'hd6;
            8'hd8: gf_inv = 8'h10;
            8'hd9: gf_inv = 8'h73;
            8'hda: gf_inv = 8'h76;
            8'hdb: gf_inv = 8'h78;
            8'hdc: gf_inv = 8'h99;
            8'hdd: gf_inv = 8'h0a;
            8'hde: gf_inv = 8'h19;
            8'hdf: gf_inv = 8'h91;
            8'he0: gf_inv = 8'h14;
            8'he1: gf_inv = 8'h3f;
            8'he2: gf_inv = 8'he6;
            8'he3: gf_inv = 8'hf0;
            8'he4: gf_inv = 8'h86;
            8'he5: gf_inv = 8'hb1;
            8'he6: gf_inv = 8'he2;
            8'he7: gf_inv = 8'hf1;
            8'he8: gf_inv = 8'hfa;
            8'he9: gf_inv = 8'h74;
            8'hea: gf_inv = 8'hf3;
            8'heb: gf_inv = 8'hb4;
            8'hec: gf_inv = 8'h6d;
            8'hed: gf_inv = 8'h21;
            8'hee: gf_inv = 8'hb2;
            8'hef: gf_inv = 8'h6a;
            8'hf0: gf_inv = 8'he3;
            8'hf1: gf_inv = 8'he7;
            8'hf2: gf_inv = 8'hb5;
            8'hf3: gf_inv = 8'hea;
            8'hf4: gf_inv = 8'h03;
            8'hf5: gf_inv = 8'h8f;
            8'hf6: gf_inv = 8'hd3;
            8'hf7: gf_inv = 8'hc9;
            8'hf8: gf_inv = 8'h42;
            8'hf9: gf_inv = 8'hd4;
            8'hfa: gf_inv = 8'he8;
            8'hfb: gf_inv = 8'h75;
            8'hfc: gf_inv = 8'h7f;
            8'hfd: gf_inv = 8'hff;
            8'hfe: gf_inv = 8'h7e;
            8'hff: gf_inv = 8'hfd;
            default: gf_inv = 8'h00;
            endcase
        end
    endfunction

    // ---------------- state ----------------
    reg [3:0]  state;
    reg [7:0]  n, wa, p, oi;
    reg [7:0]  cw [0:254];
    reg [8*NSYM-1:0]     S;        // syndromes
    reg [8*(NSYM+1)-1:0] Lam, B;   // locator / helper polynomial (index = degree)
    reg [8*NSYM-1:0]     Om;       // evaluator
    reg [8*(NSYM+1)-1:0] lam_t;    // Chien running terms
    reg [8*NSYM-1:0]     om_t;
    reg [7:0]  f_t, bb;
    reg [4:0]  L, m, r;
    reg [3:0]  nroots, ai;
    reg        fail;
    reg [8*T-1:0] epos, eval;

    assign s_ready = (state == S_LOAD);
    assign m_valid = (state == S_OUT);
    assign m_data  = cw[p];

    // ---------------- combinational datapath ----------------
    integer i, j;
    reg [8*NSYM-1:0]     S_next;
    reg [7:0]            disc, coef, omc, lsum, lodd, osum, ev;
    reg [8*(NSYM+1)-1:0] Lam_upd, lam_t_next;
    reg [8*NSYM-1:0]     om_t_next;
    always @* begin
        // syndrome update with incoming byte
        for (j = 0; j < NSYM; j = j + 1)
            S_next[j*8 +: 8] = gf_mul((wa == 0) ? 8'd0 : S[j*8 +: 8], gf_exp((FCR + j) % 255)) ^ s_data;
        // BM discrepancy + candidate update
        disc = S[r*8 +: 8];
        for (i = 1; i <= NSYM; i = i + 1)
            if (i <= L && i <= r)
                disc = disc ^ gf_mul(Lam[i*8 +: 8], S[(r-i)*8 +: 8]);
        coef = gf_mul(disc, gf_inv(bb));
        for (i = 0; i <= NSYM; i = i + 1)
            Lam_upd[i*8 +: 8] = Lam[i*8 +: 8] ^ ((i >= m) ? gf_mul(coef, B[(i-m)*8 +: 8]) : 8'd0);
        // Omega coefficient oi
        omc = 8'd0;
        for (j = 0; j < NSYM; j = j + 1)
            if (j <= oi)
                omc = omc ^ gf_mul(S[(oi-j)*8 +: 8], Lam[j*8 +: 8]);
        // Chien / Forney evaluation at alpha^-p
        lsum = 8'd0; lodd = 8'd0; osum = 8'd0;
        for (j = 0; j <= NSYM; j = j + 1) begin
            lsum = lsum ^ lam_t[j*8 +: 8];
            if (j % 2 == 1) lodd = lodd ^ lam_t[j*8 +: 8];
            lam_t_next[j*8 +: 8] = gf_mul(lam_t[j*8 +: 8], gf_exp((255 - (j % 255)) % 255));
        end
        for (j = 0; j < NSYM; j = j + 1) begin
            osum = osum ^ om_t[j*8 +: 8];
            om_t_next[j*8 +: 8] = gf_mul(om_t[j*8 +: 8], gf_exp((255 - (j % 255)) % 255));
        end
        ev = gf_mul(gf_mul(f_t, osum), gf_inv(lodd));
    end

    // ---------------- FSM ----------------
    always @(posedge clk) begin
        st_done <= 1'b0; st_fail <= 1'b0; st_nerr <= 4'd0;
        if (rst) begin
            state <= S_LOAD; wa <= 0; p <= 0;
        end else case (state)
            S_LOAD: if (s_valid) begin
                if (wa == 0) n <= cfg_rs_n;
                cw[wa] <= s_data;
                S <= S_next;
                if (wa != 0 && wa == n - 1'b1) begin
                    wa <= 0; state <= S_CHECK;
                end else
                    wa <= wa + 1'b1;
            end
            S_CHECK: begin
                fail <= 1'b0; nroots <= 0; ai <= 0;
                if (S == 0) begin
                    p <= 0; state <= S_OUT;
                end else begin
                    Lam <= 1; B <= 1; L <= 0; m <= 1; bb <= 8'd1; r <= 0;
                    state <= S_BM;
                end
            end
            S_BM: begin
                if (disc == 8'd0)
                    m <= m + 1'b1;
                else begin
                    Lam <= Lam_upd;
                    if (2*L <= r) begin
                        B <= Lam; L <= r + 1'b1 - L; bb <= disc; m <= 1;
                    end else
                        m <= m + 1'b1;
                end
                r <= r + 1'b1;
                if (r == NSYM - 1) begin oi <= 0; state <= S_OMEGA; end
            end
            S_OMEGA: begin
                if (L > T) begin
                    fail <= 1'b1; state <= S_DECIDE;
                end else begin
                    Om[oi*8 +: 8] <= omc;
                    oi <= oi + 1'b1;
                    if (oi == NSYM - 1) state <= S_CINIT;
                end
            end
            S_CINIT: begin
                lam_t <= Lam; om_t <= Om; f_t <= 8'd1; p <= 0;
                state <= S_CHIEN;
            end
            S_CHIEN: begin
                if (lsum == 8'd0) begin
                    if (lodd == 8'd0 || nroots >= T)
                        fail <= 1'b1;
                    else begin
                        epos[nroots*8 +: 8] <= n - 1'b1 - p;
                        eval[nroots*8 +: 8] <= ev;
                        nroots <= nroots + 1'b1;
                    end
                end
                lam_t <= lam_t_next;
                om_t  <= om_t_next;
                f_t   <= gf_mul(f_t, gf_exp((255 - (FCR % 255)) % 255));
                p     <= p + 1'b1;
                if (p == n - 1'b1) state <= S_DECIDE;
            end
            S_DECIDE: begin
                if (fail || nroots != L) begin
                    fail <= 1'b1; nroots <= 0;
                end
                ai <= 0;
                state <= S_APPLY;
            end
            S_APPLY: begin
                if (ai == nroots) begin
                    p <= 0; state <= S_OUT;
                end else begin
                    cw[epos[ai*8 +: 8]] <= cw[epos[ai*8 +: 8]] ^ eval[ai*8 +: 8];
                    ai <= ai + 1'b1;
                end
            end
            S_OUT: if (m_ready) begin
                if (p == n - NSYM - 1) begin
                    state   <= S_LOAD;
                    st_done <= 1'b1;
                    st_fail <= fail;
                    st_nerr <= nroots;
                end else
                    p <= p + 1'b1;
            end
            default: state <= S_LOAD;
        endcase
    end
endmodule
